// Fetch every URL and report what came back. No judgement here on
// purpose: a status code is a fact, and this node is allowed to write
// facts straight to the table. Anything needing an opinion goes to the
// review queue instead.

const results = [];

for (const item of $input.all()) {
  const { id, certification_id, url } = item.json;

  let status = 0;
  let error = null;

  try {
    // GET, not HEAD: plenty of course platforms answer 405 or 404 to a
    // HEAD while serving the page fine on GET. A HEAD-based checker
    // reports healthy links as dead, which is worse than not checking.
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      followRedirect: true,
      timeout: 20000,
      headers: {
        // Cloudflare and friends serve 403 to anything that looks
        // scripted, which would read as a dead link on a fine page.
        'user-agent':
          'Mozilla/5.0 (compatible; SkillStackBot/1.0; +https://github.com/alm7zm/Skill_Stack)',
        accept: 'text/html,application/xhtml+xml',
      },
    });
    status = res.statusCode;
  } catch (e) {
    // DNS failure, TLS failure, timeout. Not an HTTP status at all.
    error = String(e.message ?? e).slice(0, 200);
  }

  // Only 404/410 mean gone. 401/403 are NOT dead — paywalled and
  // login-walled resources are still real, and many legitimately refuse
  // a bot. 5xx is the site having a bad day: retry next week rather than
  // hide someone's course. 0 means we never reached it at all, which is
  // as likely to be our network as their server.
  const gone = status === 404 || status === 410;

  results.push({
    json: {
      resource_id: id,
      certification_id,
      url,
      http_status: status,
      error,
      gone,
      checked_at: new Date().toISOString(),
    },
  });
}

return results;
